import Image from "next/image";

type PhotoSlotProps = Readonly<{ label: string; className?: string; src?: string }>;
export function PhotoSlot({ label, className = "", src }: PhotoSlotProps) {
  return <div className={`photo-slot ${src ? "has-image" : ""} ${className}`} role={src ? undefined : "img"} aria-label={src ? undefined : `${label}. Approved MSA photography to be added.`}>
    {src ? <Image className="photo-asset" src={src} alt={label} fill sizes="(max-width: 700px) 100vw, 60vw" /> : null}
    <div className="photo-slot-copy"><span>MSA BIT JAIPUR</span><strong>{label}</strong>{src ? null : <small>APPROVED PHOTOGRAPHY PENDING</small>}</div>
  </div>;
}
